Let me try a simpler approach - just run the commands separately:

<｜｜DSML｜｜=execute_bash>
<parameter=command>cat > /tmp/test_fuzzer2.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "hiredis.h"

int main(int argc, char **argv) {
    if (argc < 2) return 0;
    FILE *f = fopen(argv[1], "rb");
    if (!f) return 0;
    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *data = malloc(size + 1);
    if (!data) return 0;
    fread(data, 1, size, f);
    data[size] = '\0';
    fclose(f);

    char *cmd;
    int ret = redisFormatCommand(&cmd, data);
    printf("ret=%d cmd=%p\n", ret, (void*)cmd);
    if (cmd != NULL) {
        printf("cmd=%s\n", cmd);
        hi_free(cmd);
    }
    free(data);
    return 0;
}
EOF</｜｜DSML｜｜>
</｜｜DSML｜｜>

